    setFavoriteIds((current) => {
      const nextFavorites = new Set(current)
      if (nextFavorites.has(taskId)) {
        nextFavorites.delete(taskId)
      } else {
        nextFavorites.add(taskId)
      }
      persist(nextFavorites)
      return nextFavorites
    })
  }, [persist])

