      for (const taskId of taskIds) {
        nextFavorites.delete(taskId)
      }
      persist(nextFavorites)
      return nextFavorites
    })
  }, [persist])

  return { favoriteIds, storageError, toggleFavorite, removeProjectFavorites }
}
